CREATE TABLE public.culture_feed(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category text NOT NULL CHECK(category IN ('movie','music','book','event')),kind text NOT NULL CHECK(kind IN ('news','release','recommendation','event')),title text NOT NULL,summary text NOT NULL DEFAULT '',image_url text,source_name text NOT NULL,source_url text NOT NULL,result jsonb,event_id uuid REFERENCES public.cultural_events(id) ON DELETE CASCADE,published_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(category,kind,source_url));
GRANT SELECT ON public.culture_feed TO authenticated;
GRANT ALL ON public.culture_feed TO service_role;
ALTER TABLE public.culture_feed ENABLE ROW LEVEL SECURITY;
CREATE POLICY feed_read ON public.culture_feed FOR SELECT TO authenticated USING(true);
CREATE TABLE public.culture_feed_likes(feed_id uuid NOT NULL REFERENCES public.culture_feed(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,PRIMARY KEY(feed_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.culture_feed_likes TO authenticated;
GRANT ALL ON public.culture_feed_likes TO service_role;
ALTER TABLE public.culture_feed_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY feed_likes_read ON public.culture_feed_likes FOR SELECT TO authenticated USING(true);
CREATE POLICY feed_likes_insert ON public.culture_feed_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY feed_likes_delete ON public.culture_feed_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.culture_feed_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),feed_id uuid NOT NULL REFERENCES public.culture_feed(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.culture_feed_comments TO authenticated;
GRANT ALL ON public.culture_feed_comments TO service_role;
ALTER TABLE public.culture_feed_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY feed_comments_read ON public.culture_feed_comments FOR SELECT TO authenticated USING(true);
CREATE POLICY feed_comments_insert ON public.culture_feed_comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY feed_comments_delete ON public.culture_feed_comments FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.culture_updates(key text PRIMARY KEY,updated_at timestamptz NOT NULL DEFAULT now(),message text);
GRANT SELECT ON public.culture_updates TO authenticated;
GRANT ALL ON public.culture_updates TO service_role;
ALTER TABLE public.culture_updates ENABLE ROW LEVEL SECURITY;
CREATE POLICY updates_read ON public.culture_updates FOR SELECT TO authenticated USING(true);